analysis/screening_run_artifacts_after_prompt_update_20260511/full_runs/gpt_oss_120b_review_pipeline_all4027_current_rep2_watchdog_20260511T1642Z/job_11575/guideline_pilot_raw_completed.jsonl:834:{"cluster_id": 890, "title": "Delineating the effective use of self-supervised learning in single-cell genomics", "title_normalized": "delineating the effective use of selfsupervised learning in singlecell genomics", "doi": "10.1038/s42256-024-00934-3", "preprint_doi": "10.1101/2024.02.16.580624", "pmid": NaN, "arxiv_id": NaN, "abstract": "{'h1': 'Abstract', 'p': ['Self-supervised learning (SSL) has emerged as a powerful method for extracting meaningful representations from vast, unlabelled datasets, transforming computer vision and natural language processing. In single-cell genomics (SCG), representation learning offers insights into the complex biological data, especially with emerging foundation models. However, identifying scenarios in SCG where SSL outperforms traditional learning methods remains a nuanced challenge. Furthermore, selecting the most effective pretext tasks within the SSL framework for SCG is a critical yet unresolved question. Here we address this gap by adapting and benchmarking SSL methods in SCG, including masked autoencoders with multiple masking strategies and contrastive learning methods. Models trained on over 20 million cells were examined across multiple downstream tasks, including cell-type prediction, gene-expression reconstruction, cross-modality prediction and data integration. Our empirical analyses underscore the nuanced role of SSL, namely, in transfer learning scenarios leveraging auxiliary data or analysing unseen datasets. Masked autoencoders excel over contrastive methods in SCG, diverging from computer vision trends. Moreover, our findings reveal the notable capabilities of SSL in zero-shot settings and its potential in cross-modality prediction and data integration. In summary, we study SSL methods in SCG on fully connected networks and benchmark their utility across key representation learning scenarios.', 'Self-supervised learning techniques are powerful assets for enabling deep insights into complex, unlabelled single-cell genomic data. Richter et al. here benchmark the applicability of self-supervised architectures into key downstream representation learning scenarios.']}", "authors": "Richter T.", "year": 2025.0, "venue": "Nature Machine Intelligence", "date": "2025-01-01", "url": NaN, "sources": "['biorxiv_medrxiv', 'scopus', 'semantic_scholar', 'springernature']", "n_sources": 4, "all_dois": "['10.1101/2024.02.16.580624', '10.1038/s42256-024-00934-3']", "duplicate_count": 4, "abstract_source": NaN, "abstract_enriched_from": NaN, "abstract_old_len": NaN, "update_batch": NaN, "_pilot_row_id": 833, "round-A_scope_reviewer_output": {"paper_type": "benchmark_resource", "bio_modality_present": "yes", "text_component_present": "no", "text_bio_bridge_present": "no", "primary_exclusion_code": "benchmark_resource", "uncertainty_reason": "none", "evidence_for_text_component": "none", "evidence_for_text_bio_bridge": "none", "evidence_for_generative_model": "not_assessed", "boundary_case": "none", "decision_rationale": "The abstract presents a benchmarking study of self‑supervised learning methods for single‑cell genomics without describing any natural‑language text component or text‑bio mapping, thus it is a benchmark/resource paper and lacks a text‑bio bridge."}, "round-A_scope_reviewer_paper_type": "benchmark_resource", "round-A_scope_reviewer_bio_modality_present": "yes", "round-A_scope_reviewer_text_component_present": "no", "round-A_scope_reviewer_text_bio_bridge_present": "no", "round-A_scope_reviewer_primary_exclusion_code": "benchmark_resource", "round-A_scope_reviewer_uncertainty_reason": "none", "round-A_scope_reviewer_evidence_for_text_component": "none", "round-A_scope_reviewer_evidence_for_text_bio_bridge": "none", "round-A_scope_reviewer_evidence_for_generative_model": "not_assessed